head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";
scwin.vCONTN_ID = "";
scwin.gEmpNo = $c.stf.getUserInfo($p, "empNo");
scwin.gEmpNm = $c.stf.getUserInfo($p, "empNm");

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 영문공시 관련 영역을 숨기고 메뉴구분 목록·화면 모드(신규/조회)·K-CLIC 상태를 초기화한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        // 영문공시제출 오픈시 아래 부분 삭제
        //--------------------------------------------------
        grp_eng_comment.hide();
        grp_eng_fil.hide();
        //----------------------------------------------------
        scwin.setMenuflag();
        sbx_MENU_FLAG.setValue("");

        scwin.initPage();
        scwin.setKclicStatus('init');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 이벤트 — 현재 별도 처리 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_AddRow_onclick
 * @description 파일 추가 버튼 클릭 이벤트 — 메뉴구분별 최대 첨부 개수(공시발간자료 6개, 그 외 5개)를 체크한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_AddRow_onclick(e);
 */
scwin.btn_AddRow_onclick = function (e) {
    try {
        // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
        if (sbx_MENU_FLAG.getValue() === "04") {
            if (dlt_FILE_LIST.getRowCount() === 6) {
                $c.win.alert("더이상 추가하실 수 없습니다.");
                return;
            }
        } else {
            if (dlt_FILE_LIST.getRowCount() === 5) {
                $c.win.alert("더이상 추가하실 수 없습니다.");
                return;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_AddRow_onclick" });
    }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description 파일 삭제 버튼 클릭 이벤트 — 체크된 행의 파일을 업로드 컴포넌트에서 제거하고 그리드에서 행을 삭제한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_DelRow_onclick(e);
 */
scwin.btn_DelRow_onclick = function (e) {
    try {
        const idxArrJson = grd_FILE_LIST.getCheckedJSON("chk");
        const idxArrIndex = grd_FILE_LIST.getCheckedIndex("chk");
        for (let i = 0; i < idxArrJson.length; i++) {
            const fileName = idxArrJson[i].attachFileNm;
            mpd_file.removeFile(fileName);
        }
        dlt_FILE_LIST.removeRows(idxArrIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_DelRow_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 저장 버튼 클릭 이벤트 — 저장 처리를 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Save_onclick(e);
 */
scwin.btn_Save_onclick = function (e) {
    try {
        scwin.save();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 삭제 버튼 클릭 이벤트 — 삭제 처리를 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Delete_onclick(e);
 */
scwin.btn_Delete_onclick = function (e) {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 취소 버튼 클릭 이벤트 — 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Cancel_onclick(e);
 */
scwin.btn_Cancel_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name grd_FILE_LIST_oncellclick
 * @description 파일목록 그리드 셀 클릭 이벤트 — 첨부파일명 클릭 시 파일을 다운로드한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_FILE_LIST_oncellclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_FILE_LIST_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.downLoad(rowIndex, columnId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.grd_FILE_LIST_oncellclick" });
    }
};

/**
 * @method
 * @name sbx_MENU_FLAG_onviewchange
 * @description 메뉴구분 콤보 변경 이벤트 — 밸류업 자료실(62/63) 선택 시 공지대상시스템 제약을 안내하고, 메뉴구분별 최대 첨부 개수를 세팅한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbx_MENU_FLAG_onviewchange(info);
 */
scwin.sbx_MENU_FLAG_onviewchange = function (info) {
    try {
        const gValueUp = sbx_MENU_FLAG.getValue();
        if (gValueUp === '62') {
            // 밸류업자료실(국문)
            rdo_mkt_gubun.setValue("9");
            rdo_mkt_gubun.setDisabled(true);
            if (cbx_OBJ_SYSTEM2.getValue() === "Y" &&
                cbx_OBJ_SYSTEM1.getValue() === "N" &&
                cbx_OBJ_SYSTEM3.getValue() === "N" &&
                cbx_OBJ_SYSTEM4.getValue() === "N" &&
                cbx_OBJ_SYSTEM5.getValue() === "N") {

            } else {
                $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(국문)]만 선택해주세요.");
            }
        } else if (gValueUp === '63') {
            // 밸류업자료실(영문)
            if (cbx_OBJ_SYSTEM2.getValue() === "N" &&
                cbx_OBJ_SYSTEM1.getValue() === "N" &&
                cbx_OBJ_SYSTEM3.getValue() === "N" &&
                cbx_OBJ_SYSTEM4.getValue() === "N" &&
                cbx_OBJ_SYSTEM5.getValue() === "Y") {

            } else {
                $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(영문)]만 선택해주세요.");
            }
        } else {
            rdo_mkt_gubun.setDisabled(false);
        }

        // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
        // if (sbx_MENU_FLAG.getValue() == "04") {
        //     if (dlt_FILE_LIST.getTotalRow() == 6) {
        //         $c.win.alert("더이상 추가하실 수 없습니다.");
        //         return;
        //     }
        // } else {
        //     if (dlt_FILE_LIST.getTotalRow() == 5) {
        //         $c.win.alert("더이상 추가하실 수 없습니다.");
        //         return;
        //     }
        // }

        if (gValueUp === "04") {
            mpd_file.setMaxFileCount(6);
        } else {
            mpd_file.setMaxFileCount(5);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.sbx_MENU_FLAG_onviewchange" });
    }
};

/**
 * @method
 * @name cbx_OBJ_SYSTEM1_onviewchange
 * @description 공지대상시스템 제출(국문) 체크 변경 이벤트 — 메뉴구분·게시물유형·담당기관 콤보 상태를 세팅하고 K-CLIC 상태를 갱신한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.cbx_OBJ_SYSTEM1_onviewchange(info);
 */
scwin.cbx_OBJ_SYSTEM1_onviewchange = function (info) {
    try {
        // 제출(국문)
        if (cbx_OBJ_SYSTEM1.getValue() === true) {
            sbx_MENU_FLAG.setDisabled(false);
            if (cbx_OBJ_SYSTEM4.getValue() === "N") {
                sbx_sprt_room_grp.setDisabled(true);
                sbx_chrg_inst_id.setDisabled(true);
                sbx_sprt_room_grp.setValue("");
                sbx_chrg_inst_id.setValue("");
            }
        }

        if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
            sbx_sprt_room_grp.setDisabled(false);
            sbx_chrg_inst_id.setDisabled(false);
            sbx_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
        }

        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.cbx_OBJ_SYSTEM1_onviewchange" });
    }
};

/**
 * @method
 * @name cbx_OBJ_SYSTEM2_onviewchange
 * @description 공지대상시스템 조회(국문) 체크 변경 이벤트 — 메뉴구분·게시물유형·담당기관 콤보 상태를 세팅하고 K-CLIC 상태를 갱신한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.cbx_OBJ_SYSTEM2_onviewchange(info);
 */
scwin.cbx_OBJ_SYSTEM2_onviewchange = function (info) {
    try {
        // 조회(국문)
        if (cbx_OBJ_SYSTEM2.getValue() === true) {
            sbx_MENU_FLAG.setDisabled(false);
            if (cbx_OBJ_SYSTEM4.getValue() === "N") {
                sbx_sprt_room_grp.setDisabled(true);
                sbx_chrg_inst_id.setDisabled(true);
                sbx_sprt_room_grp.setValue("");
                sbx_chrg_inst_id.setValue("");
            }
        }

        if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
            sbx_sprt_room_grp.setDisabled(false);
            sbx_chrg_inst_id.setDisabled(false);
            sbx_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
        }

        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.cbx_OBJ_SYSTEM2_onviewchange" });
    }
};

/**
 * @method
 * @name cbx_OBJ_SYSTEM4_onviewchange
 * @description 공지대상시스템 K-CLIC 체크 변경 이벤트 — K-CLIC 상태를 갱신한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.cbx_OBJ_SYSTEM4_onviewchange(info);
 */
scwin.cbx_OBJ_SYSTEM4_onviewchange = function (info) {
    try {
        // K-CLIC
        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.cbx_OBJ_SYSTEM4_onviewchange" });
    }
};

/**
 * @method
 * @name cbx_OBJ_SYSTEM5_onviewchange
 * @description 공지대상시스템 조회(영문) 체크 변경 이벤트 — 체크 시 밸류업 자료실(영문)으로 고정하고 다른 시스템 체크를 해제·비활성화한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.cbx_OBJ_SYSTEM5_onviewchange(info);
 */
scwin.cbx_OBJ_SYSTEM5_onviewchange = function (info) {
    try {
        // 조회(영문)
        if (cbx_OBJ_SYSTEM5.getValue() === true) {
            scwin.setMenuflag("eng");
            sbx_MENU_FLAG.setValue("63");
            sbx_MENU_FLAG.setDisabled(true);
            rdo_mkt_gubun.setValue("9");
            rdo_mkt_gubun.setDisabled(true);
            sbx_sprt_room_grp.setDisabled(true);
            sbx_chrg_inst_id.setDisabled(true);
            sbx_sprt_room_grp.setValue("");
            sbx_chrg_inst_id.setValue("");

            if (cbx_OBJ_SYSTEM4.getValue() === true || cbx_OBJ_SYSTEM3.getValue() === true ||
                cbx_OBJ_SYSTEM2.getValue() === true || cbx_OBJ_SYSTEM1.getValue() === true) {
                $c.win.alert("조회(영문) 시스템은 다른 시스템과 같이 사용할 수 없습니다.");
            }

            cbx_OBJ_SYSTEM4.setValue("N");
            cbx_OBJ_SYSTEM4.setDisabled(true);
            cbx_OBJ_SYSTEM3.setValue("N");
            cbx_OBJ_SYSTEM3.setDisabled(true);
            cbx_OBJ_SYSTEM2.setValue("N");
            cbx_OBJ_SYSTEM2.setDisabled(true);
            cbx_OBJ_SYSTEM1.setValue("N");
            cbx_OBJ_SYSTEM1.setDisabled(true);
        } else {
            scwin.setMenuflag("ko");
            sbx_MENU_FLAG.setValue("");
            sbx_MENU_FLAG.setDisabled(false);
        }

        if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
            sbx_sprt_room_grp.setDisabled(false);
            sbx_chrg_inst_id.setDisabled(false);
            sbx_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
            cbx_OBJ_SYSTEM4.setDisabled(false);
            cbx_OBJ_SYSTEM3.setDisabled(false);
            cbx_OBJ_SYSTEM2.setDisabled(false);
            cbx_OBJ_SYSTEM1.setDisabled(false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.cbx_OBJ_SYSTEM5_onviewchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name selectCallback
 * @description 파일업로드시 파일정보 dataList에 세팅 — 파일명 길이(80byte)·확장자·크기(30MB)를 체크한 후 dlt_FILE_LIST 에 행을 추가한다.
 * @returns {void}
 * @hidden N
 * @example scwin.selectCallback();
 */
scwin.selectCallback = function () {
    const fileInfos = mpd_file.getFileInfos();
    // dlt_FILE_LIST.setJSON(fileInfos);

    for (let i = 0; i < fileInfos.length; i++) {
        const vFileNm = fileInfos[i].name;
        const vSize = fileInfos[i].size;

        if (vFileNm !== "") {
            // 파일 확장자 체크 추가
            if (scwin.checkMaxLength1(vFileNm, '80', "파일명")) return; // 파일명 80자 체크
            if (scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크

            if (!scwin.canUploadFile(vSize)) {
                $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
                return;
            } else {
                let newRow = dlt_FILE_LIST.insertRow();
                dlt_FILE_LIST.setCellData(newRow, "attachFileNm", returnArr[i]);
            }
        } else {
            return;
        }
    }    
};

/**
 * @method
 * @name sbm_Save_submitdone
 * @description 저장/삭제 서브미션 완료 콜백 — 성공 시 완료 메시지 표시 후 부모 화면 목록을 재조회하고 팝업을 닫는다.
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_Save_submitdone(e);
 */
scwin.sbm_Save_submitdone = async function (e) {
    if (!e.responseJSON.success) {
        return;
    }

    const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    $p.parent().scwin.fn_listDsclBbs();
    $c.win.closePopup();
};

/**
 * @method
 * @name save
 * @description 저장 처리 — 입력 폼 검증(checkForm) 후 저장 확인을 받아 게시물 등록 서브미션을 수행하고 첨부파일 업로드를 시작한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.save();
 */
scwin.save = async function () {
    if (scwin.checkForm() === false) return;

    const res = await $c.win.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "저장";
        const url = "/IntegratedBBS.do?method=registerDsclBbs" + "&SCREN_ID=" + "ULDSTF30403.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInputMaster=dlt_MASTER, I:pFile=dlt_FILE_LIST)";
        $c.sbm.setAction(sbm_Save, url);
        const sbmOptions = {
            id : "sbm_Save",
            action : "/api/discls/issueinfo/update-new-password-approval",
            ref : "dma_MASTER",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_Save_submitdone(sbmRtn);
        //--------------------------------------------------

        mpd_file.changeAction("http://localhost/api/discls/dsclinfo/insert-notice-content");	// action 설정

        const param = { "wrtrEmail": "eds@krx.co.kr", "notiEndDd": "20261224", "pw": "1234", "notiObjSysTpCd": "1,2,3,B", "wrtrEmpNm": "시스템관리자", "bbsTpCd": "03", "mktTpCd": "1", "title": "공지사항 - 제출", "contnMaindocContn": "string", "notiStrtDd": "20260601", "chrgInstId": "KRX" };
        mpd_file.setParam(0, "data", JSON.stringify(param));	// data param 설정
        mpd_file.startUpload();
    }
};

/**
 * @method
 * @name delete
 * @description 삭제 처리 — 비밀번호 입력을 확인하고 삭제 확인을 받아 게시물 삭제 서브미션을 수행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.delete();
 */
scwin.delete = async function () {
    const vPW = ibx_PW.getValue();
    if (vPW === "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        // ibx_PW.focus();
        return;
    }

    const res = await $c.win.confirm("[삭제]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "삭제";
        const url = "/IntegratedBBS.do?method=removeDsclBbs" + "&SCREN_ID=" + "ULDSTF30403.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.KeyValue = "JSP(I:pInputMaster=dlt_MASTER)";
        $c.sbm.setAction(sbm_Save, url);
        const sbmOptions = {
            id : "sbm_Save",
            action : "/api/discls/issueinfo/update-new-password-approval",
            ref : "dma_MASTER",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_Save_submitdone(sbmRtn);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description 화면 모드 초기화 — 팝업 ID가 신규(INTEBBS_NEW)면 등록자 정보를 세팅하고 삭제 버튼을 숨기며, 그 외에는 게시물 ID를 받아 수정 모드(setEditMode)로 진입한다.
 * @returns {void}
 * @hidden N
 * @example scwin.initPage();
 */
scwin.initPage = function () {
    if ($p.getPopupId().includes("INTEBBS_NEW")) {
        // gfm은 정적인 화면이라 변수값을 받을 수 없어. 창의 이름으로 신규와 수정을 구별한다. 
        ibx_WRTR_EMP_NO.setValue(scwin.gEmpNo);
        ibx_WRTR_EMP_NM.setValue(scwin.gEmpNm);
        btn_Delete.hide();
    } else {
        scwin.vCONTN_ID = $c.data.getParameter("contnId");
        scwin.setEditMode();
    }
};

/**
 * @method
 * @name setMenuflag
 * @description 메뉴구분 목록 세팅 — 공시발간자료·자료실·공시체크포인트·업무사례·밸류업자료실(국문) 코드를 구성하고, 구분이 "eng"이면 밸류업자료실(영문)을 추가한다.
 * @param {String} gubun 구분("eng"이면 영문 밸류업자료실 포함)
 * @returns {void}
 * @hidden N
 * @example scwin.setMenuflag("eng");
 */
scwin.setMenuflag = function (gubun) {
    dlt_MENU_FLAG.setJSON([]);
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(0, "code", "04");
    dlt_MENU_FLAG.setCellData(0, "codeNm", "공시발간자료");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(1, "code", "02");
    dlt_MENU_FLAG.setCellData(1, "codeNm", "자료실");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(2, "code", "31");
    dlt_MENU_FLAG.setCellData(2, "codeNm", "공시체크포인트");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(3, "code", "32");
    dlt_MENU_FLAG.setCellData(3, "codeNm", "업무사례");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(4, "code", "62");
    dlt_MENU_FLAG.setCellData(4, "codeNm", "밸류업자료실(국문)");

    if (gubun === "eng") {
        dlt_MENU_FLAG.insertRow();
        dlt_MENU_FLAG.setCellData(5, "code", "63");
        dlt_MENU_FLAG.setCellData(5, "codeNm", "밸류업자료실(영문)");
    }
};

/**
 * @method
 * @name setEditMode
 * @description 수정 모드 진입 — 게시물 ID로 게시물 본문과 첨부파일 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.setEditMode();
 */
scwin.setEditMode = async function () {
    let url = "/IntegratedBBS.do?method=readDsclBbs";
    url += "&CONTN_ID=" + scwin.vCONTN_ID;

    $c.sbm.setAction(sbm_MASTER, url);
    let ret = await $c.sbm.execute(sbm_MASTER);

    url = "/IntegratedBBS.do?method=listInteBBSAttach";
    url += "&CONTN_ID=" + scwin.vCONTN_ID;

    $c.sbm.setAction(sbm_FILE_LIST, url);
    ret = await $c.sbm.execute(sbm_FILE_LIST);
};

/**
 * @method
 * @name checkForm
 * @description 저장 전 입력 폼 검증 — 등록자·공지대상시스템·이메일·비밀번호·제목·메뉴구분·시장구분·내용의 필수/형식과 메뉴구분별 제약(공시체크포인트·업무사례·밸류업자료실·K-CLIC), 게시기간을 검증한다.
 * @returns {Boolean} 검증 통과 시 true, 실패 시 false
 * @hidden N
 * @example if (scwin.checkForm() === false) return;
 */
scwin.checkForm = function () {
    if (ibx_WRTR_EMP_NM.getValue() === "") {
        $c.win.alert("[등록자]를 입력하세요.");
        return false;
    }
    if (ibx_WRTR_EMP_NM.getValue().length > 10) {
        $c.win.alert("[등록자]명을 10자 이내로 입력해 주세요.");
        ibx_WRTR_EMP_NM.focus();
        return false;
    }
    if (cbx_OBJ_SYSTEM1.getValue() === "N" &&
        cbx_OBJ_SYSTEM2.getValue() === "N" &&
        cbx_OBJ_SYSTEM3.getValue() === "N" &&
        cbx_OBJ_SYSTEM4.getValue() === "N" &&
        cbx_OBJ_SYSTEM5.getValue() === "N") {
        $c.win.alert("[공지대상시스템]를 선택하세요.");
        return false;
    }
    if (ibx_WRTR_EMAIL.getValue() === "") {
        $c.win.alert("[이메일]를 입력하세요.");
        ibx_WRTR_EMAIL.focus();
        return false;
    }
    if ($c.stf.IsValidEmail(ibx_WRTR_EMAIL.getValue()) === false) {
        $c.win.alert("[이메일] 정확하지 않습니다.");
        ibx_WRTR_EMAIL.focus();
        return false;
    }
    if (ibx_PW.getValue() === "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        // ibx_PW.focus();
        return false;
    }
    if (ibx_TITLE.getValue() === "") {
        $c.win.alert("[제목]를 입력하세요.");
        ibx_TITLE.focus();
        return false;
    }
    if (sbx_MENU_FLAG.getValue() === "" && cbx_OBJ_SYSTEM4.getValue() !== true) {
        $c.win.alert("[메뉴구분]를 선택하세요.");
        sbx_MENU_FLAG.focus();
        return false;
    }
    if (rdo_mkt_gubun.getValue() === "") {
        $c.win.alert("[시장구분]를 선택하세요.");
        rdo_mkt_gubun.focus();
        return false;
    }
    if (txa_CONTN_CONTN.getValue() === "") {
        $c.win.alert("[내용]를 입력하세요.");
        txa_CONTN_CONTN.focus();
        return false;
    }

    if (sbx_MENU_FLAG.getValue() === "31" || sbx_MENU_FLAG.getValue() === "32") {
        if (sbx_MENU_FLAG.getValue() === "31" && (cbx_OBJ_SYSTEM1.getValue() === "N" || (cbx_OBJ_SYSTEM1.getValue() === "Y" && cbx_OBJ_SYSTEM2.getValue() === "Y"))) {
            $c.win.alert("[공시체크포인트]는 제출시스템에만 적용됩니다.<br>공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "32" && (cbx_OBJ_SYSTEM1.getValue() === "N" || (cbx_OBJ_SYSTEM1.getValue() === "Y" && cbx_OBJ_SYSTEM2.getValue() === "Y"))) {
            $c.win.alert("[업무사례]는 제출시스템에만 적용됩니다.<br>공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "31" && rdo_mkt_gubun.getValue() === "4") {
            $c.win.alert("[공시체크포인트]은 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "32" && rdo_mkt_gubun.getValue() === "4") {
            $c.win.alert("[업무사례]는 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
    }
    // 202405 밸류업 추가 
    if (sbx_MENU_FLAG.getValue() === "62") {
        if (cbx_OBJ_SYSTEM2.getValue() === "Y" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "N") {

        } else {
            $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(국문)]만 선택하여주세요.");
            return false;
        }
    }
    if (sbx_MENU_FLAG.getValue() === "63") {
        if (cbx_OBJ_SYSTEM2.getValue() === "N" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "Y") {

        } else {
            $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(영문)]만 선택하여주세요.");
            return false;
        }
    }
    if (cbx_OBJ_SYSTEM4.getValue() === "Y") {
        // K-CLIC 
        if (sbx_sprt_room_grp.getValue() === "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 게시물유형을 선택해 주세요.");
            sbx_sprt_room_grp.focus();
            return false;
        }
        if (sbx_chrg_inst_id.getValue() === "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 담당기관을 선택해 주세요.");
            sbx_chrg_inst_id.focus();
            return false;
        }
    }

    // 날짜확인
    if (!$c.stf.compareFromToDate2(ica_SDate, ica_EDate)) {
        ica_SDate.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name downLoad
 * @description 첨부파일 다운로드 — 첨부파일명 컬럼 클릭 시 게시물 ID·첨부순번으로 파일 다운로드를 수행한다.
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 ID
 * @returns {void}
 * @hidden N
 * @example scwin.downLoad(0, "attachFileNm");
 */
scwin.downLoad = function (row, colid) {
    const filename = dlt_FILE_LIST.getCellData(row, "attachFileNm");

    if (filename === "") return;

    if (colid === "attachFileNm") {
        const contnId = dlt_FILE_LIST.getCellData(row, "contnId");
        const contnAttachSeq = dlt_FILE_LIST.getCellData(row, "contnAttachSeq");
        let url = "/api/discls/common/file/download";
        url += "?gubun=2&contnId=" + contnId + "&contnAttachSeq=" + contnAttachSeq;

        $p.download(url, {}, "get", true);
    }
};

/**
 * @method
 * @name setKclicStatus
 * @description K-CLIC 상태 갱신 — 공지대상시스템 체크 조합에 따라 게시물유형·담당기관·메뉴구분·시장구분의 활성/비활성과 값을 세팅한다.
 * @param {String} status 상태 구분("init"이면 초기화 시점으로 메뉴구분 값 변경 생략)
 * @returns {void}
 * @hidden N
 * @example scwin.setKclicStatus("init");
 */
scwin.setKclicStatus = function (status) {
    if (cbx_OBJ_SYSTEM4.getValue() === true) {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        if (cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
            if ('init' !== status) {
                sbx_MENU_FLAG.setValue("02");
            }
            sbx_MENU_FLAG.setDisabled(true);
        }
    } else if (cbx_OBJ_SYSTEM5.getValue() === true) {
        scwin.setMenuflag("eng");
        sbx_MENU_FLAG.setValue("63");
        sbx_MENU_FLAG.setDisabled(true);
        rdo_mkt_gubun.setValue("9");
        rdo_mkt_gubun.setDisabled(true);
        sbx_sprt_room_grp.setDisabled(true);
        sbx_chrg_inst_id.setDisabled(true);
        sbx_sprt_room_grp.setValue("");
        sbx_chrg_inst_id.setValue("");
        cbx_OBJ_SYSTEM4.setValue("N");
        cbx_OBJ_SYSTEM4.setDisabled(false);
        cbx_OBJ_SYSTEM3.setValue("N");
        cbx_OBJ_SYSTEM3.setDisabled(false);
        cbx_OBJ_SYSTEM2.setValue("N");
        cbx_OBJ_SYSTEM2.setDisabled(false);
        cbx_OBJ_SYSTEM1.setValue("N");
        cbx_OBJ_SYSTEM1.setDisabled(false);
    } else {
        sbx_sprt_room_grp.setDisabled(true);
        sbx_chrg_inst_id.setDisabled(true);
        sbx_sprt_room_grp.setValue("");
        sbx_chrg_inst_id.setValue("");
        sbx_MENU_FLAG.setDisabled(false);
    }

    if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        sbx_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }
};

/**
 * @method
 * @name canUploadFile
 * @description 파일 업로드 가능 여부 확인 — 파일 크기가 30MB 미만인지 검사한다.(2017-02-13 FileSizeLimit 30MB)
 * @param {Number} size 파일 크기(byte)
 * @returns {Boolean} 업로드 가능하면 true, 30MB 이상이면 false
 * @hidden N
 * @example if (!scwin.canUploadFile(vSize)) return;
 */
scwin.canUploadFile = function (size) {
    const maxFileSize = 1024 * 1024 * 30; // 30MB		
    if (size < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name checkExtension
 * @description 파일 확장자 체크 — 허가 확장자 목록에 없는 확장자면 업로드 불가 알림 후 true 를 반환한다.(20250718 파일 확장자 체크로직 추가)
 * @param {String} fileNm 파일명
 * @returns {Boolean} 업로드 불가 확장자면 true, 허가 확장자면 false
 * @hidden N
 * @example if (scwin.checkExtension(vFileNm)) return;
 */
scwin.checkExtension = function (fileNm) {
    const fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png", ".zip"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    const ext = fileNm.substr(fileNm.lastIndexOf(".")).toLowerCase();
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts || fileExts[i] === ext) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};

/**
 * @method
 * @name checkMaxLength1
 * @description 최대 길이(byte) 체크 — 문자열이 지정 byte 를 초과하면 초과량 알림 후 true 를 반환한다.(한글 2byte, 숫자·영문 1byte)
 * @param {String} filestr 검사할 문자열
 * @param {String|Number} size 최대 길이(byte)
 * @param {String} lbl 알림에 표시할 항목명
 * @returns {Boolean} 초과 시 true, 이내면 false
 * @hidden N
 * @example if (scwin.checkMaxLength1(vFileNm, '80', "파일명")) return;
 */
scwin.checkMaxLength1 = function (filestr, size, lbl) {
    const overLen = $c.stf.getStringSize(filestr) - size;
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 의 최대길이는 [ " + size + " ] byte 입니다.    <br>[ " + overLen + " ] byte 를 초과하였습니다.<br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return true;
    }
    return false;
};
